Get real-time quotes for one or more option contracts by instrument UUID, plus the official prior-session close for each. This tool is part of plugin `Robinhood MCP`.

exec tool declaration:
```ts
declare const tools: { mcp__codex_apps__robinhood_get_option_quotes(args: {
  // Option instrument UUIDs. Above 20, quotes still return but closes is omitted with closes_error set.
  instrument_ids: null | Array<string>;
}): Promise<CallToolResult<{
  // Tool-specific result payload; see the inner properties for fields.
  data: {
  // Populated when the closes lookup is skipped or fails tool-wide (e.g. too many contracts, upstream timeout, no previous_close_date). Per-contract gaps surface as a missing close on the affected result, not here.
  closes_error?: string;
  // One entry per requested contract, in upstream quote order, each carrying the live quote and (when available) the official prior-session close. Empty if no instrument_id resolved.
  results: null | Array<null | {
  // Official settled close from the most recent completed session. Absent when closes_error is set, or when this contract had no close in an otherwise-successful closes batch.
  close?: null | {
  // YYYY-MM-DD date this close corresponds to. May be earlier than the requested date when interpolated.
  date: null | string;
  // UUID of the option contract; the canonical match key against quotes[].instrument_id.
  instrument_id: string;
  // True when the close came from a different date than requested (illiquid contract with no print on the requested day).
  interpolated: null | boolean;
  // Official settled close price. Null when the upstream has no close (rare; usually illiquid expired contracts).
  price: null | string;
  // Upstream provenance (e.g. 'sip-close'). Informational.
  source: null | string;
  // Underlying ticker. NOT unique — many contracts share a symbol.
  symbol: string;
};
  // Live market data for this option contract.
  quote: null | {
  // Mark adjusted for corporate actions on the underlying. Use against historical cost basis.
  adjusted_mark_price: string;
  // Lowest current sell-side price. Zero when the book is closed or unavailable.
  ask_price: string;
  // Total contracts available at ask_price.
  ask_size: number;
  // Highest current buy-side price. Zero when the book is closed or unavailable.
  bid_price: string;
  // Total contracts bid at bid_price.
  bid_size: number;
  // Underlying price at which the position breaks even at expiration (strike +/- premium).
  break_even_price: string;
  // Model probability the long side ends in profit at expiration, decimal.
  chance_of_profit_long: null | string;
  // Model probability the short side ends in profit at expiration, decimal.
  chance_of_profit_short: null | string;
  // Sensitivity of option price to a $1 move in the underlying.
  delta: null | string;
  // Rate of change of delta per $1 move in the underlying.
  gamma: null | string;
  // Upper bound of the likely fast-fill range for a buy.
  high_fill_rate_buy_price: string;
  // Upper bound of the likely fast-fill range for a sell.
  high_fill_rate_sell_price: string;
  // Market-implied future volatility, decimal (0.30 = 30%).
  implied_volatility: null | string;
  // UUID of the option contract; the canonical match key against closes[].instrument_id.
  instrument_id: string;
  // Lower bound of the likely fast-fill range for a buy.
  low_fill_rate_buy_price: string;
  // Lower bound of the likely fast-fill range for a sell.
  low_fill_rate_sell_price: string;
  // Mid-market fair value — canonical current price for valuation.
  mark_price: string;
  // Outstanding contracts not yet closed or expired.
  open_interest: number;
  // YYYY-MM-DD trading date that previous_close_price corresponds to.
  previous_close_date: string;
  // Quote-derived prior close — best-effort, not the official settled close.
  previous_close_price: string;
  // Sensitivity to a 1% change in interest rates.
  rho: null | string;
  // Daily time decay ($/day); negative for long positions.
  theta: null | string;
  // ISO 8601 timestamp of the quote refresh.
  updated_at: string;
  // Sensitivity to a 1% change in implied volatility.
  vega: null | string;
  // Total contracts traded today.
  volume: number;
};
}>;
};
  // Each entry in results pairs the live quote with the official prior-session close for the same option contract. Current price: use quote.mark_price (adjusted_mark_price when comparing against historical cost basis); verify quote.updated_at is recent before calling it 'current' — otherwise phrase as 'as of <updated_at>'. 1D P&L per contract: (quote.mark_price - close.price) × multiplier × position_quantity (multiplier is typically 100; use trade_value_multiplier from get_option_positions for adjusted contracts). Prefer results[].close.price (official settled close) over quote.previous_close_price; when a result is missing close — either closes_error is set tool-wide, or this contract had no close in an otherwise-successful batch — fall back to quote.previous_close_price and tell the user the official close lookup is unavailable. When close.interpolated is true, surface close.date — the price is not from the requested day. Drop bid/ask when zero.
  guide: string;
}>>; };
